import GallerySectionV2 from "./components/gallery-section-v2"

export default function Page() {
  return <GallerySectionV2 />
}

import { GalleryCard } from "./gallery-card"
import { galleryItems } from "../lib/config"

export default function GallerySectionV2() {
  return (
    <section className="py-4 md:py-6 lg:py-8">
      <div className="mx-auto max-w-7xl px-4">
        <h2 className="mb-6 text-4xl font-medium leading-[1.1] tracking-[-0.03em] lg:text-5xl">
          Gallery
        </h2>
        <div className="grid grid-cols-3 gap-x-6 gap-y-10">
          {galleryItems.map((item) => (
            <GalleryCard
              key={item.id}
              item={item}
            />
          ))}
        </div>
      </div>
    </section>
  )
}

import Image from "next/image"

import type { GalleryItem } from "../lib/config"

const BLUR_PLACEHOLDER = "data:image/gif;base64,R0lGODlhAQABAIAAAMLCwgAAACH5BAAAAAAALAAAAAABAAEAAAICRAEAOw=="

type GalleryCardProps = {
  item: GalleryItem
}

export function GalleryCard({ item }: GalleryCardProps) {
  return (
    <div className="group">
      <div className="relative aspect-4/3 overflow-hidden">
        <Image
          src={item.imageSrc}
          alt={item.alt}
          className="rounded-none object-cover grayscale transition-[filter] duration-500 group-hover:grayscale-0"
          fill
          loading="lazy"
          placeholder="blur"
          blurDataURL={item.blurDataURL ?? BLUR_PLACEHOLDER}
          sizes="(max-width: 1023px) 100vw, 33vw"
        />
      </div>
      <div className="mt-3 font-mono">
        <p className="text-sm font-medium leading-tight">{item.title}</p>
        <p className="mt-1 text-xs text-muted-foreground">{item.description}</p>
      </div>
    </div>
  )
}
